<script lang="ts">
import { defineComponent } from "vue";
import NuiComponentMixin from "@/mixins/NuiComponentMixin";
import { ShopFake } from "@/fakebackend/shopFake";
import { IMenuShop } from "@/interfaces/IMenuShop";
import paginationComponentVue from "@/utils/paginationComponent.vue";
import ShopCurrencyDiamondIcon from "@/components/shop/shop-currency-diamond-icon.vue";
import { ISubMenuShop } from "@/interfaces/ISubMenuShop";
import { IShop } from "@/interfaces/IShop";
import { IItemShop } from "@/interfaces/IItemsShop";

const jsonClone = <T extends object | undefined>(obj: T): T => obj === undefined ? undefined : JSON.parse(JSON.stringify(obj));

const emptySubMenu: ISubMenuShop = { name: "", items: [] };
const getFirstSubMenu = (menu: IMenuShop | undefined): ISubMenuShop =>
  menu?.subMenu?.length ? menu.subMenu[0] : emptySubMenu;

export default defineComponent({
  name: "cDevShop",
  components: {
    paginationComponentVue,
    ShopCurrencyDiamondIcon,
  },
  mixins: [NuiComponentMixin],
  data() {
    return {
      shop: ShopFake,
      selectedMenu: {} as IMenuShop | undefined,
      selectedSubMenu: {} as ISubMenuShop | undefined,
      searchSubMenu: {} as ISubMenuShop | undefined,
      currentPage: 0,
      itemsPerPage: 10,
      gridResizeObserver: null as ResizeObserver | null,
      recalcLayoutTimer: null as ReturnType<typeof setTimeout> | null,
      screenWidth: 0,
      balance: 0,
      customCurrencyBalance: 0,
      customCurrencyLabel: "",
      customCurrencyIcon: "",
      logo: "https://static.cdev.shop/resources/vehicle-shop/thumbnails/cdev.png",
      searchQuery: "",
      /** Acordeão: expandir/recolher por índice (independente da seleção do grid). */
      expandedMainByIdx: {} as Record<number, boolean>,
    };
  },
  computed: {
    safeMaxPage(): number {
      const len = this.searchSubMenu?.items?.length ?? 0;
      const perPage = Math.max(1, this.itemsPerPage || 10);
      const max = Math.ceil(len / perPage);
      return Number.isFinite(max) && max >= 0 ? max : 0;
    },
    safeShopItems(): IItemShop[] {
      const items = this.searchSubMenu?.items ?? [];
      const perPage = Math.max(1, this.itemsPerPage || 10);
      const start = (this.currentPage || 0) * perPage;
      const end = start + perPage;
      return items.slice(start, end).filter((x): x is IItemShop => x != null && typeof x === "object");
    },
  },
  props: {
    name: {
      type: String,
    },
    visible: {
      type: Boolean,
    },
    locale: {
      type: Function,
      required: true,
    },
  },
  methods: {
    /** Badge VIP só quando o Lua envia vip (UseVIPSystem ligado no pet shop + item.vip na config). */
    shopItemShowsVipBadge(item: IItemShop | undefined | null): boolean {
      if (item == null || typeof item !== "object") return false;
      return item.vip === true;
    },
    formatMoney(value: unknown): string {
      const num = value != null && value !== "" ? Number(value) : 0;
      const safe = Number.isFinite(num) ? num : 0;
      return String(safe).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    },
    /**
     * Pixels de 1 "rem" no layout. shop-app.scss: .ct-container-shop { width: 155rem }.
     * this.$el é a raiz (.ct-container-shop) — evita 0/closest em iframes ou ref atrasada.
     */
    getShopRemPx(): number {
      const root = this.$el as HTMLElement;
      if (root?.getBoundingClientRect) {
        const w = root.getBoundingClientRect().width;
        if (w > 0) return w / 155;
      }
      return Math.max(1, parseFloat(getComputedStyle(document.documentElement).fontSize) || 10);
    },
    /** Converte "12px" / "1.5rem" (primeiro token) a px, usando remPx. */
    parseLengthToPx(value: string, remPx: number): number {
      if (!value || !value.trim()) return 0;
      const t = value.trim().split(/\s+/)[0] as string;
      if (t.endsWith("px")) return parseFloat(t) || 0;
      if (t.endsWith("rem")) return (parseFloat(t) || 0) * remPx;
      return 0;
    },
    /**
     * Área interna usável pelo grid (padding 2rem 3rem do .top-body-right-body-shop-app) +
     * fallback: altura entre a barra de busca e a paginação, se clientHeight do viewport vier curto (CEF).
     */
    getGridContentBoxPx(el: HTMLElement, remPx: number) {
      // Alinhar a .top-body-right-body-shop-app (shop-app.scss: padding: 1.5rem 2.5rem)
      const padH = 2.5 * remPx * 2;
      const padV = 1.5 * remPx * 2;
      let w = el.clientWidth - padH;
      let h = el.clientHeight - padV;
      const rectH = el.getBoundingClientRect().height;
      if (rectH > 0) {
        h = Math.max(h, rectH - padV);
      }
      const parent = el.parentElement;
      if (parent && parent.classList.contains("body-right-body-shop-app")) {
        const pag = parent.querySelector<HTMLElement>(".ct-bottom-body-right-body-shop-app");
        if (pag) {
          const c = getComputedStyle(parent);
          const g = this.parseLengthToPx(c.gap, remPx) || 1.5 * remPx;
          const hBetween = parent.clientHeight - pag.offsetHeight - g;
          if (hBetween > 0) {
            h = Math.max(h, hBetween - padV);
          }
        }
      }
      return { innerW: w, innerH: h };
    },
    /**
     * Colunas/linhas: 1) mede gap + primeiro card no DOM, se existir; 2) fallback por rem (SCSS).
     */
    recalculateItemsPerPage() {
      const el = this.$refs.gridViewportRef as HTMLElement | undefined;
      if (!el) return;
      const remPx = this.getShopRemPx();
      const { innerW, innerH } = this.getGridContentBoxPx(el, remPx);
      if (innerW < 1 || innerH < 1) return;

      const gridEl = el.querySelector<HTMLElement>(".top-body-right-body-shop-app");
      const cGrid = gridEl ? getComputedStyle(gridEl) : null;
      const gapF = 1.25 * remPx;
      const gCol = cGrid
        ? this.parseLengthToPx(cGrid.columnGap, remPx) || this.parseLengthToPx(cGrid.gap, remPx)
        : gapF;
      const gRow = cGrid
        ? this.parseLengthToPx(cGrid.rowGap, remPx) || this.parseLengthToPx(cGrid.gap, remPx)
        : gapF;
      const gapW = gCol > 0 ? gCol : gapF;
      const gapH = gRow > 0 ? gRow : gapF;

      const firstItem = el.querySelector<HTMLElement>(
        ".ct-item-top-body-right-body-shop-app .item-top-body-right-body-shop-app"
      );
      const br = firstItem ? firstItem.getBoundingClientRect() : null;
      const colW = br && br.width > 4 ? br.width : 20 * remPx;
      const rowH = br && br.height > 4 ? br.height : 22 * remPx;

      const cols = Math.max(1, Math.floor((innerW + gapW) / (colW + gapW)));
      const rows = Math.max(1, Math.floor((innerH + gapH) / (rowH + gapH)));
      const next = Math.max(1, Math.min(240, cols * rows));

      if (this.itemsPerPage !== next) {
        this.itemsPerPage = next;
      }
      const perPage = Math.max(1, this.itemsPerPage);
      const len = this.searchSubMenu?.items?.length ?? 0;
      const maxPageIdx = len ? Math.max(0, Math.ceil(len / perPage) - 1) : 0;
      this.currentPage = Math.min(this.currentPage, maxPageIdx);
    },
    initGridLayoutObserver() {
      const el = this.$refs.gridViewportRef as HTMLElement | undefined;
      if (typeof ResizeObserver === "undefined" || !el) {
        this.recalculateItemsPerPage();
        return;
      }
      if (this.gridResizeObserver) {
        this.gridResizeObserver.disconnect();
        this.gridResizeObserver = null;
      }
      this.gridResizeObserver = new ResizeObserver(() => {
        this.recalculateItemsPerPage();
      });
      this.gridResizeObserver.observe(el);
      this.recalculateItemsPerPage();
    },
    handleNUI({ action, data }: { action: string; data: unknown }) {
      if (action === "setShop") {
        const { shop } = data as { shop: IShop };

        this.shop = shop ?? this.shop;
        this.customCurrencyBalance = 0;
        this.customCurrencyLabel = "";
        this.customCurrencyIcon = "";
        const firstMenu = this.shop?.mainMenu?.length ? this.shop.mainMenu[0] : undefined;
        this.selectedMenu = firstMenu;
        const firstSub = getFirstSubMenu(firstMenu);
        this.selectedSubMenu = firstSub;
        this.searchSubMenu = jsonClone(firstSub) ?? emptySubMenu;
        this.currentPage = 0;
        this.initializeExpandedState();
        this.$nextTick(() => {
          this.recalculateItemsPerPage();
          requestAnimationFrame(() => {
            this.recalculateItemsPerPage();
          });
        });
      } else if (action == "setBalance") {
        const { balance } = data as { balance?: number };

        this.balance = balance != null && Number.isFinite(Number(balance)) ? Number(balance) : 0;
      } else if (action === "setCustomCurrencyBalance") {
        const { balance, currencyKey, currencyLabel } = data as {
          balance?: number | null;
          currencyKey?: string | null;
          currencyLabel?: string | null;
        };
        if (balance == null && currencyLabel == null) {
          this.customCurrencyBalance = 0;
          this.customCurrencyLabel = "";
        } else {
          this.customCurrencyBalance =
            balance != null && Number.isFinite(Number(balance)) ? Number(balance) : 0;
          this.customCurrencyLabel =
            typeof currencyLabel === "string" && currencyLabel
              ? currencyLabel
              : typeof currencyKey === "string" && currencyKey
                ? currencyKey
                : "";
        }
      } else if (action === "setCustomCurrencyIcon") {
        const { iconUrl } = data as { iconUrl?: string | null };
        this.customCurrencyIcon = typeof iconUrl === "string" && iconUrl !== "" ? iconUrl : "";
      } else if (action == "setLogo") {
        const { logo } = data as { logo: string };

        this.logo = logo;
      }
    },
    handleKeyDown(e: KeyboardEvent) {
      if (!this.visible) return;

      if (e.key === "Escape") {
        this.postNUI("close", {});
      }
    },
    /** Mapa todas fechadas (acordeão). */
    collapsedExpandedMap(): Record<number, boolean> {
      const menus = this.shop?.mainMenu ?? [];
      const o: Record<number, boolean> = {};
      for (let i = 0; i < menus.length; i++) {
        o[i] = false;
      }
      return o;
    },
    /** Acordeão exclusivo: só uma categoria expandida (abrir uma fecha as outras). */
    expandOnlyMain(mi: number) {
      const o = this.collapsedExpandedMap();
      o[mi] = true;
      this.expandedMainByIdx = o;
    },
    initializeExpandedState() {
      const menus = this.shop?.mainMenu ?? [];
      const o = this.collapsedExpandedMap();
      const idx = menus.findIndex((m) => m.name === this.selectedMenu?.name);
      if (idx >= 0) {
        o[idx] = true;
      } else if (menus.length > 0) {
        o[0] = true;
      }
      this.expandedMainByIdx = o;
    },
    isMainExpanded(mi: number): boolean {
      return this.expandedMainByIdx[mi] === true;
    },
    toggleMainExpand(mi: number) {
      if (!this.isMainExpanded(mi)) {
        this.expandOnlyMain(mi);
        return;
      }
      const o = this.collapsedExpandedMap();
      this.expandedMainByIdx = o;
    },
    onSelectMainCategory(mainItem: IMenuShop) {
      this.setSelectedMenu(mainItem);
    },
    setSelectedMenu(menu: IMenuShop) {
      this.selectedMenu = menu;
      const firstSub = getFirstSubMenu(menu);
      this.selectedSubMenu = firstSub;
      this.searchSubMenu = jsonClone(firstSub) ?? emptySubMenu;
      this.currentPage = 0;
      const idx = this.shop?.mainMenu?.findIndex((m) => m.name === menu.name) ?? -1;
      if (idx >= 0) {
        this.expandOnlyMain(idx);
      }
      this.$nextTick(() => {
        this.recalculateItemsPerPage();
        requestAnimationFrame(() => this.recalculateItemsPerPage());
      });
    },
    setSelectedSubMenu(subMenu: ISubMenuShop) {
      this.selectedSubMenu = subMenu;
      this.searchSubMenu = jsonClone(subMenu);
      this.currentPage = 0;
      this.$nextTick(() => {
        this.recalculateItemsPerPage();
        requestAnimationFrame(() => this.recalculateItemsPerPage());
      });
    },
    selectSubFromSidebar(subMenu: ISubMenuShop) {
      const menus = this.shop?.mainMenu ?? [];
      const parentIdx = menus.findIndex((m) =>
        m?.subMenu?.some((s) => s?.name === subMenu?.name),
      );
      if (parentIdx >= 0) {
        this.expandOnlyMain(parentIdx);
      }
      this.setSelectedSubMenu(subMenu);
    },
    buyItem(button: string, item: IItemShop) {
      this.postNUI("buyItem", { button, item });
    },
    addCountItem(item: IItemShop) {
      if (item.lockQuantity) return;

      item.quantity = Math.min(
        (item.quantity || 0) + 1,
        item.maxQuantity || Infinity
      );
      //this.postNUI("updateItemCount", { item });
    },
    decreaseCountItem(item: IItemShop) {
      if (item.lockQuantity) return;

      item.quantity = Math.max((item.quantity || 0) - 1, item.minQuantity || 0);
      //this.postNUI("updateItemCount", { item });
    },
    handleChangePage(page: number) {
      const max = this.safeMaxPage;
      this.currentPage = Math.max(0, Math.min(page - 1, max - 1));
    },
    getScreenSize() {
      this.screenWidth = window.innerWidth;
      this.$nextTick(() => {
        this.recalculateItemsPerPage();
      });
    },
    handleSearch() {
      if (this.searchSubMenu && this.selectedSubMenu) {
        const filteredItems = this.selectedSubMenu.items.filter((item) => {
          return item.name.trim().toLowerCase().includes(this.searchQuery.trim().toLowerCase()) || this.searchQuery.trim() === "";
        });
        // Sempre copiar o array para não partilhar referência com selectedSubMenu.items (evita travamentos ao mudar de página/categoria)
        this.searchSubMenu.items = filteredItems.slice();
      }
    },
    onShopImageError(e: Event) {
      const el = (e.target as HTMLImageElement);
      if (!el || (el as any).__shopPlaceholder) return;
      (el as any).__shopPlaceholder = true;
      el.onerror = null;
      el.src = "nui://cdev_pets/html/pets/inventory/placeholder.webp";
    },
  },
  watch: {
    visible(newVal: boolean) {
      if (newVal) {
        this.$nextTick(() => {
          this.recalculateItemsPerPage();
          this.initGridLayoutObserver();
        });
      }
    },
  },
  updated() {
    if (this.visible === false) return;
    if (this.recalcLayoutTimer) {
      clearTimeout(this.recalcLayoutTimer);
    }
    this.recalcLayoutTimer = setTimeout(() => {
      this.recalcLayoutTimer = null;
      this.recalculateItemsPerPage();
    }, 100);
  },
  mounted: function () {
    window.addEventListener("keydown", this.handleKeyDown);
    window.addEventListener("resize", this.getScreenSize);
    this.$nextTick(() => {
      this.initGridLayoutObserver();
    });
  },
  unmounted: function () {
    window.removeEventListener("keydown", this.handleKeyDown);
    window.removeEventListener("resize", this.getScreenSize);
    if (this.recalcLayoutTimer) {
      clearTimeout(this.recalcLayoutTimer);
      this.recalcLayoutTimer = null;
    }
    if (this.gridResizeObserver) {
      this.gridResizeObserver.disconnect();
      this.gridResizeObserver = null;
    }
  },
  created: function () {
    const firstMenu = this.shop?.mainMenu?.length ? this.shop.mainMenu[0] : undefined;
    this.selectedMenu = firstMenu;
    const firstSub = getFirstSubMenu(firstMenu);
    this.selectedSubMenu = firstSub;
    this.searchSubMenu = jsonClone(firstSub) ?? emptySubMenu;
    this.initializeExpandedState();
    this.getScreenSize();
  },
});
</script>
